-- IDSER-001: Atlas-owned candidate pipeline foundation. No execution is activated here.
ALTER TABLE atlas.workspace ADD COLUMN IF NOT EXISTS display_name text;
UPDATE atlas.workspace SET display_name = CASE kind WHEN 'master' THEN 'Master' WHEN 'initial_draft' THEN 'Initial Draft' ELSE kind END WHERE display_name IS NULL;
ALTER TABLE atlas.workspace ALTER COLUMN display_name SET NOT NULL;
ALTER TABLE atlas.workspace DROP CONSTRAINT IF EXISTS workspace_project_kind_key;
ALTER TABLE atlas.workspace DROP CONSTRAINT IF EXISTS workspace_kind_check;
ALTER TABLE atlas.workspace ADD CONSTRAINT workspace_kind_check CHECK (kind <> '');
ALTER TABLE atlas.workspace DROP CONSTRAINT IF EXISTS workspace_state_check;
ALTER TABLE atlas.workspace ADD CONSTRAINT workspace_state_check CHECK ((kind = 'master' AND state = 'empty') OR (kind = 'initial_draft' AND state IN ('draft', 'ready_for_review')) OR (kind NOT IN ('master', 'initial_draft')));
CREATE UNIQUE INDEX IF NOT EXISTS workspace_system_kind_unique ON atlas.workspace(project_id, kind) WHERE kind IN ('master', 'initial_draft');

CREATE TABLE atlas.extraction_bundle (id text PRIMARY KEY, project_id text NOT NULL REFERENCES atlas.project(id) ON DELETE CASCADE, workspace_id text NOT NULL, state text NOT NULL CHECK (state IN ('waiting','processing','ready_for_review','needs_attention')), semantic_contract_version text NOT NULL, reconciliation_contract_version text NOT NULL, expected_document_count integer NOT NULL CHECK (expected_document_count > 0), completed_document_count integer NOT NULL DEFAULT 0 CHECK (completed_document_count BETWEEN 0 AND expected_document_count), created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, completed_at timestamptz, last_failure_code text, last_failure_at timestamptz, FOREIGN KEY (project_id, workspace_id) REFERENCES atlas.workspace(project_id, id), CHECK ((state = 'waiting' AND started_at IS NULL AND completed_at IS NULL) OR (state = 'processing' AND started_at IS NOT NULL AND completed_at IS NULL) OR (state = 'ready_for_review' AND completed_at IS NOT NULL AND completed_document_count = expected_document_count) OR state = 'needs_attention'));
CREATE TABLE atlas.extraction_bundle_document (bundle_id text NOT NULL REFERENCES atlas.extraction_bundle(id) ON DELETE CASCADE, document_id text NOT NULL REFERENCES atlas.document(id) ON DELETE CASCADE, sequence integer NOT NULL CHECK (sequence > 0), state text NOT NULL CHECK (state IN ('pending','perception_queued','perceiving','extracting','reconciling','completed','needs_attention')), perception_execution_id text, semantic_extraction_execution_id text, semantic_reconciliation_execution_id text, started_at timestamptz, completed_at timestamptz, last_failure_code text, last_failure_at timestamptz, PRIMARY KEY(bundle_id, document_id), UNIQUE(bundle_id, sequence), CHECK ((state = 'pending' AND started_at IS NULL AND completed_at IS NULL) OR (state = 'completed' AND completed_at IS NOT NULL) OR state NOT IN ('pending','completed')));
CREATE OR REPLACE FUNCTION atlas.assert_bundle_manifest_mutable() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE bundle_state text; bundle_id_value text; BEGIN IF TG_OP = 'DELETE' THEN bundle_id_value := OLD.bundle_id; ELSE bundle_id_value := NEW.bundle_id; END IF; SELECT state INTO bundle_state FROM atlas.extraction_bundle WHERE id = bundle_id_value; IF bundle_state IS NOT NULL AND bundle_state <> 'waiting' THEN RAISE EXCEPTION 'extraction bundle manifest is immutable after processing starts'; END IF; IF TG_OP = 'DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER extraction_bundle_document_manifest_immutable BEFORE INSERT OR UPDATE OR DELETE ON atlas.extraction_bundle_document FOR EACH ROW EXECUTE FUNCTION atlas.assert_bundle_manifest_mutable();
CREATE TABLE atlas.semantic_execution (id text PRIMARY KEY, project_id text NOT NULL, workspace_id text NOT NULL, bundle_id text NOT NULL REFERENCES atlas.extraction_bundle(id) ON DELETE CASCADE, document_id text NOT NULL, stage text NOT NULL CHECK (stage IN ('extraction','reconciliation')), contract_version text NOT NULL, skill_version text NOT NULL, logical_identity text NOT NULL, lifecycle text NOT NULL CHECK (lifecycle IN ('queued','running','completed','failed')), authorized_context_identity text NOT NULL, authorized_context_fingerprint text NOT NULL, capability_valid_until timestamptz NOT NULL, completion_fingerprint text, failure_code text, failure_detail text, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, FOREIGN KEY (bundle_id, document_id) REFERENCES atlas.extraction_bundle_document(bundle_id, document_id), UNIQUE(bundle_id, document_id, stage, contract_version), UNIQUE(bundle_id, document_id, stage, contract_version, completion_fingerprint), CHECK ((lifecycle = 'completed') = (completion_fingerprint IS NOT NULL)));
CREATE TABLE atlas.semantic_extraction_result (id text PRIMARY KEY, execution_id text NOT NULL UNIQUE REFERENCES atlas.semantic_execution(id), project_id text NOT NULL, workspace_id text NOT NULL, bundle_id text NOT NULL, document_id text NOT NULL, contract_version text NOT NULL, source_sha256 text NOT NULL CHECK (source_sha256 ~ '^[a-f0-9]{64}$'), provider_provenance jsonb NOT NULL CHECK (jsonb_typeof(provider_provenance) = 'object'), result_json jsonb NOT NULL CHECK (jsonb_typeof(result_json) = 'object'), completion_fingerprint text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (bundle_id, document_id) REFERENCES atlas.extraction_bundle_document(bundle_id, document_id));
CREATE TABLE atlas.semantic_candidate (id text PRIMARY KEY, extraction_result_id text NOT NULL REFERENCES atlas.semantic_extraction_result(id), project_id text NOT NULL, workspace_id text NOT NULL, bundle_id text NOT NULL, document_id text NOT NULL, semantic_key text NOT NULL, kind text NOT NULL, payload jsonb NOT NULL CHECK (jsonb_typeof(payload) = 'object'), normalized_meaning text NOT NULL, source_wording text, needs_resolution boolean NOT NULL, state text NOT NULL CHECK (state = 'candidate'), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (bundle_id, document_id) REFERENCES atlas.extraction_bundle_document(bundle_id, document_id));
CREATE TABLE atlas.semantic_evidence (id text PRIMARY KEY, semantic_candidate_id text NOT NULL REFERENCES atlas.semantic_candidate(id), document_id text NOT NULL REFERENCES atlas.document(id), page_number integer NOT NULL CHECK (page_number > 0), locator_type text NOT NULL, locator_id text NOT NULL, excerpt text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE atlas.knowledge_index (semantic_id text PRIMARY KEY, project_id text NOT NULL, workspace_id text NOT NULL, bundle_id text NOT NULL, document_id text NOT NULL, semantic_key text NOT NULL, kind text NOT NULL, semantic_candidate_id text NOT NULL UNIQUE REFERENCES atlas.semantic_candidate(id), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (bundle_id, document_id) REFERENCES atlas.extraction_bundle_document(bundle_id, document_id));
CREATE TABLE atlas.semantic_reconciliation_result (id text PRIMARY KEY, execution_id text NOT NULL UNIQUE REFERENCES atlas.semantic_execution(id), project_id text NOT NULL, workspace_id text NOT NULL, bundle_id text NOT NULL REFERENCES atlas.extraction_bundle(id), current_document_id text NOT NULL REFERENCES atlas.document(id), contract_version text NOT NULL, provider_provenance jsonb NOT NULL CHECK (jsonb_typeof(provider_provenance) = 'object'), result_json jsonb NOT NULL CHECK (jsonb_typeof(result_json) = 'object'), completion_fingerprint text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE atlas.reconciliation_relationship (id text PRIMARY KEY, reconciliation_result_id text NOT NULL REFERENCES atlas.semantic_reconciliation_result(id), project_id text NOT NULL, workspace_id text NOT NULL, bundle_id text NOT NULL REFERENCES atlas.extraction_bundle(id), source_semantic_id text NOT NULL REFERENCES atlas.knowledge_index(semantic_id), target_semantic_id text REFERENCES atlas.knowledge_index(semantic_id), relationship_type text NOT NULL, payload jsonb NOT NULL CHECK (jsonb_typeof(payload) = 'object'), requires_resolution boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bridge.semantic_result_delivery (idempotency_key text PRIMARY KEY, execution_id text NOT NULL, stage text NOT NULL CHECK (stage IN ('extraction','reconciliation')), validated_envelope jsonb NOT NULL CHECK (jsonb_typeof(validated_envelope) = 'object'), provenance jsonb NOT NULL CHECK (jsonb_typeof(provenance) = 'object'), completion_fingerprint text NOT NULL, delivered_at timestamptz, cleanup_after timestamptz, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE atlas.extraction_bundle OWNER TO atlas_app;
ALTER TABLE atlas.extraction_bundle_document OWNER TO atlas_app;
ALTER TABLE atlas.semantic_execution OWNER TO atlas_app;
ALTER TABLE atlas.semantic_extraction_result OWNER TO atlas_app;
ALTER TABLE atlas.semantic_candidate OWNER TO atlas_app;
ALTER TABLE atlas.semantic_evidence OWNER TO atlas_app;
ALTER TABLE atlas.knowledge_index OWNER TO atlas_app;
ALTER TABLE atlas.semantic_reconciliation_result OWNER TO atlas_app;
ALTER TABLE atlas.reconciliation_relationship OWNER TO atlas_app;
ALTER TABLE bridge.semantic_result_delivery OWNER TO agents_bridge;
REVOKE ALL ON TABLE atlas.extraction_bundle, atlas.extraction_bundle_document, atlas.semantic_execution, atlas.semantic_extraction_result, atlas.semantic_candidate, atlas.semantic_evidence, atlas.knowledge_index, atlas.semantic_reconciliation_result, atlas.reconciliation_relationship FROM PUBLIC, agents_bridge;
REVOKE ALL ON TABLE bridge.semantic_result_delivery FROM PUBLIC, atlas_app;
INSERT INTO atlas.schema_migrations (name) VALUES ('0009_idser001_domain_persistence_foundation') ON CONFLICT DO NOTHING;
